window.ComicVaultPressFilms1059=Object.assign(Object.create(null),{[window.ComicVaultPressData1057.filmId]:window.ComicVaultPressData1057},{"friday-the-13th-part-2-1981-theatrical":{"filmId":"friday-the-13th-part-2-1981-theatrical","filmTitle":"Friday the 13th Part 2 (1981)","scopeNote":"Fictional newspaper recreations inspired by the separately scoped 1981 film. Reporting, illustrations and advertisements are imagined, not original props or historical records.","sources":{"F132-PARAMOUNT":{"id":"F132-PARAMOUNT","title":"Paramount: Friday the 13th Part II","label":"Paramount: Friday the 13th Part II","url":"https://www.paramount.com/movies/friday-the-13th-part-ii","kind":"official studio","note":"Metadata, principal cast and five-years-after premise. Use 87-minute catalog runtime.","access":"Public web source reviewed 2026-10-19.","filmFootageViewed":false,"fullIssueRead":false},"F132-AFI":{"id":"F132-AFI","title":"AFI Catalog: Friday the 13th Part 2","label":"AFI Catalog: Friday the 13th Part 2","url":"https://catalog.afi.com/Film/56617-FRIDAY-THE13THPART2","kind":"film archive","note":"Credits, May 1 opening, production history and synopsis. Synopsis simplifies some action details; do not use it to resolve ending ambiguity.","access":"Public web source reviewed 2026-10-19.","filmFootageViewed":false,"fullIssueRead":false},"F132-DIALOGUE":{"id":"F132-DIALOGUE","title":"Part 2 dialogue transcription","label":"Part 2 dialogue transcription","url":"https://www.scripts.com/script/friday_the_13th_part_2:_jason_8598","kind":"unofficial dialogue transcription","note":"Paul describes Alice disappearing two months afterward, then a five-year interval, and says the old camp is off-limits. Not a verified shooting script.","access":"Public web source reviewed 2026-10-19.","filmFootageViewed":false,"fullIssueRead":false},"F132-PLOT":{"id":"F132-PLOT","title":"Part 2 plot cross-check","label":"Part 2 plot cross-check","url":"https://en.wikipedia.org/wiki/Friday_the_13th_Part_2","kind":"secondary reference","note":"Useful scene-order cross-check; its exact 1984/1979 calendar assignments are not adopted.","access":"Public web source reviewed 2026-10-19.","filmFootageViewed":false,"fullIssueRead":false},"F132-FUREY":{"id":"F132-FUREY","title":"John Furey profile and interview excerpt","label":"John Furey profile and interview excerpt","url":"https://fridaythe13thfilms.com/saga/part2/johnfurey.html","kind":"secondary archive with attributed quotation","note":"Rejects the walk-off rumor and describes unresolved Paul ending. No claim of direct access to underlying production documents.","access":"Public web source reviewed 2026-10-19.","filmFootageViewed":false,"fullIssueRead":false}},"editions":[{"id":"f132-alice-disappearance","publication":"The Lake District Weekly","dateLabel":"After Alice’s disappearance","shortLabel":"After the prologue · A survivor missing","imageFilename":"f132-lake-district-weekly-alice-missing.png","imageAlt":"Fictional cream-and-burgundy Lake District Weekly front page reporting Alice missing after the Crystal Lake killings, with an imagined residential street, four article blocks and three period advertisements.","width":1024,"height":1536,"imageStatus":"Approved fictional recreation","archiveNote":"FICTIONAL RECREATION · Friday the 13th Part 2 (1981).\nRelative chronology only: Alice disappears two months after the earlier camp killings.\nAll newspaper reporting, editorials, illustrations, merchants and advertisements are invented. Alice is reported missing, not publicly confirmed dead. No known killer is identified. No image is a film still, film prop or historical record.","canonAnchors":[{"detail":"Paul’s later campfire account says the earlier survivor disappeared two months afterward.","sourceIds":["F132-DIALOGUE"]},{"detail":"The audience sees Alice killed in the prologue, but that is not the same as a public police finding.","sourceIds":["F132-PLOT"]}],"articles":[{"id":"f132-alice-main","headline":"CRYSTAL LAKE SURVIVOR MISSING","deck":"Alice’s disappearance brings new concern after camp tragedy","paragraphs":["Alice, the young woman who survived the killings at Camp Crystal Lake, has disappeared. Two months after the camp tragedy, her absence has brought another painful uncertainty to the lake district.","What has become of her remains unknown. There is no established account of where she has gone, and this newspaper is reporting her disappearance, not a confirmed death.","For a community still troubled by the summer’s violence, the news is difficult to separate from memories of the camp. Yet concern for Alice must come before speculation. Anyone with direct knowledge of her whereabouts should contact the proper authorities, rather than pass another story along the town’s rumor circuit."],"imageCaption":"An imagined residential street in the lake district."},{"id":"f132-alice-editorial","headline":"More than a survivor","label":"EDITORIAL","paragraphs":["To most readers, Alice is the young woman who came out of Crystal Lake alive. That description tells us something terrible she endured. It does not tell us the whole of her life.","The public’s curiosity is understandable. Its first concern should nevertheless be her safety. A missing person deserves more than a place in a frightening story. There is room in this week’s news for patience, compassion and respect for private grief."],"imageCaption":"The lake’s troubled past casts a long shadow."},{"id":"f132-alice-background","headline":"The shadow of Crystal Lake","paragraphs":["The camp’s name has become shorthand for the district’s darkest news. Its abandoned cabins and wooded paths are familiar subjects of local talk.","Alice’s disappearance will bring those conversations back. The earlier killings are part of the background, but they are not an explanation for every unanswered question. A place can acquire a reputation faster than a town can learn the truth."]},{"id":"f132-alice-notice","headline":"From the editor’s desk","paragraphs":["This newspaper welcomes firsthand information, not retellings of retellings. Names, times and direct observations are more useful than the most elaborate theory.","Please respect private homes and the people who live in them. The search for news is no excuse for turning someone else’s doorstep into a public attraction."]}]},{"id":"f132-packanack-training","publication":"The Lake District Weekly","dateLabel":"Training-camp arrival period","shortLabel":"Before the attacks · A new season nearby","imageFilename":"f132-lake-district-weekly-packanack-opening.png","imageAlt":"Fictional Lake District Weekly front page welcoming counselors to Packanack, with an imagined lodge, four articles and three period advertisements. It distinguishes the training grounds from the closed original Camp Crystal Lake.","width":1024,"height":1536,"imageStatus":"Approved fictional recreation","archiveNote":"FICTIONAL RECREATION · Friday the 13th Part 2 (1981).\nSet during the counselors’ arrival, before the principal attacks. No exact calendar date is asserted.\nTraining under Paul Holt near the abandoned Camp Crystal Lake is the film anchor. All newspaper copy, illustrations, merchants and advertisements are imagined.","articles":[{"id":"f132-training-main","headline":"NEW COUNSELORS AT PACKANACK","deck":"Training begins near Crystal Lake; old camp remains off-limits","paragraphs":["Paul Holt is welcoming a new group of prospective counselors to Packanack. Bags are coming off car seats, cabin doors are opening and the familiar work of getting settled is beginning.","The training grounds are near Crystal Lake, but this is not a reopening of the old Camp Crystal Lake. The abandoned property remains separate from the active program and is off-limits to the newcomers.","For the young people arriving, the days ahead are meant to be about learning the responsibilities of a counselor. For a district accustomed to darker stories about its lake, an ordinary afternoon of introductions and unpacking offers a different sort of news."],"imageCaption":"An imagined view of the training grounds before the season’s work."},{"id":"f132-training-boundary","headline":"The old camp is off-limits","label":"KNOW THE BOUNDARY","paragraphs":["A short walk through the woods can lead beyond the training grounds. The old Crystal Lake camp is not part of Paul Holt’s program, however familiar its name may be.","Closed buildings and overgrown paths are not an invitation to explore. There is plenty to learn at the new camp without turning a free afternoon into a visit to the abandoned one."],"imageCaption":"Wooded paths can carry a visitor beyond familiar ground."},{"id":"f132-training-notice","headline":"Learning the ropes","paragraphs":["A counselor’s kit is more than a packed bag. A working flashlight, dry socks and a sound pair of shoes may help, but patience and attention are just as useful.","Knowing the grounds and looking after one another are ordinary habits worth acquiring early. The little preparations made in daylight have a way of becoming important after sunset."]},{"id":"f132-training-editorial","headline":"A new season, an old story","label":"EDITORIAL","paragraphs":["The lake’s reputation arrives before the newcomers do. Some will hear a warning; others will hear a story to repeat around a fire.","A legend is not a safety plan. Whatever anyone believes about Crystal Lake, respect for closed property and care for the people beside you remain sensible places to begin."]}],"ads":[{"merchant":"HARRIS SPORTING GOODS","tagline":"Ready for a new season?","products":"PACKS • CANTEENS • CAMP SUPPLIES","closing":"Equipment for the great outdoors.","illustration":"canvas backpack and metal canteen"},{"merchant":"BELL RADIO & ELECTRIC","tagline":"Before sunset, check your batteries","products":"FLASHLIGHTS • BATTERIES • REPAIRS","closing":"Ask for a demonstration.","illustration":"period metal flashlight and two dry-cell batteries"},{"merchant":"LAKESIDE GROCERY","tagline":"One last stop before camp","products":"FRESH BREAD • COFFEE • GROCERIES","closing":"Friendly service at the counter.","illustration":"paper grocery bag with bread and coffee tin"}],"canonAnchors":[{"detail":"A counselor-training operation is established near the abandoned original camp.","sourceIds":["F132-PARAMOUNT"]},{"detail":"Paul says Camp Crystal Lake is off-limits.","sourceIds":["F132-DIALOGUE"]}]},{"id":"f132-packanack-aftermath","publication":"The Lake District Weekly","dateLabel":"Morning after the Packanack attacks","shortLabel":"Morning edition · Rescue and uncertainty","imageFilename":"f132-lake-district-weekly-packanack-aftermath.png","imageAlt":"Fictional Lake District Weekly morning front page reporting Ginny taken away alive by ambulance after violence at Packanack. An imagined rescue scene, four articles and three period advertisements preserve uncertainty about Paul Holt and the final casualty list.","width":1024,"height":1536,"imageStatus":"Approved fictional recreation","archiveNote":"FICTIONAL RECREATION · Friday the 13th Part 2 (1981), theatrical-ending boundary.\nThe closing morning sequence shows Ginny alive and taken to an ambulance; she asks for Paul.\nAll newspaper reporting, illustrations, merchants and advertisements are invented. The page does not identify the attacker, settle Paul’s fate, give a final victim count, certify the window attack or assert a supernatural explanation.","articles":[{"id":"f132-aftermath-main","headline":"TERROR AT PACKANACK","deck":"Ginny leaves by ambulance after night of violence","paragraphs":["A young woman known to the counselors as Ginny was brought out alive and taken away by ambulance this morning after violence at the Packanack training camp. Her departure offers a sign of rescue, but not a full account of the night.","This edition has no confirmed final account of casualties. The names and number of victims remain unsettled, and a complete account of those at the grounds is still awaited.","The training camp stands near the abandoned Crystal Lake property. It is a separate place, not a reopening of the old camp. As the district waits for dependable news, memories of the earlier tragedy are no substitute for answers about what has happened here."],"imageCaption":"An imagined morning rescue scene. Not a photograph from the film."},{"id":"f132-aftermath-paul","headline":"Questions surround Paul Holt","label":"UNANSWERED QUESTIONS","paragraphs":["Ginny was heard asking for Paul as she was taken away. That question provides no certain answer about his whereabouts or condition. This newspaper has no confirmed account of what happened to him.","Until there is dependable word, an unanswered question must not be turned into a death notice. His fate remains unresolved in this morning’s report."],"imageCaption":"A quiet path through the training grounds."},{"id":"f132-aftermath-editorial","headline":"Let the rescue come first","label":"EDITORIAL","paragraphs":["There will be time to ask how this could happen. This morning belongs first to those who need help and to those waiting for word of someone they know.","The district owes them patience. Concern is not measured by how quickly a rumor can travel, but by the care taken before it is passed along."]},{"id":"f132-aftermath-notice","headline":"Keep the roads clear","label":"COMMUNITY NOTICE","paragraphs":["Curiosity is no reason to make a trip to the camp. Leave the approaches clear for those whose work takes them there, and do not stop a vehicle simply to get a better view.","Families and neighbors will need room to hear the news in their own time. Help begins with giving them that room."]}],"ads":[{"merchant":"LAKESIDE GROCERY","tagline":"Your neighborhood counter","products":"BREAD • MILK • COFFEE • GROCERIES","closing":"Friendly service. Everyday essentials.","illustration":"simple milk bottle, bread loaf and coffee tin"},{"merchant":"MILLER’S HARDWARE","tagline":"For the jobs around home","products":"TOOLS • LAMPS • HOUSEHOLD GOODS","closing":"Practical supplies. Personal service.","illustration":"period metal oil lamp and small hand tools"},{"merchant":"BELL RADIO & ELECTRIC","tagline":"A familiar voice at home","products":"TABLE RADIOS • BATTERIES • REPAIRS","closing":"Ask for a demonstration.","illustration":"small period tabletop transistor radio"}],"canonAnchors":[{"detail":"The closing morning sequence shows Ginny alive and being taken to an ambulance.","sourceIds":["F132-AFI"]},{"detail":"Paul is not accounted for conclusively in the released ending.","sourceIds":["F132-FUREY"]}]}],"imageBase":"assets/newspapers/friday13-part2/","imageVersion":"10.59","archiveTitle":"THE CRYSTAL LAKE PRESS ARCHIVE","archiveDescription":"Three fictional editions, from Alice’s disappearance to the Packanack aftermath.","provenance":"Fictional local reporting and period advertisements inspired by Friday the 13th Part 2 (1981). Reporting follows each edition’s point in the story; publication names, articles and advertisements are not authentic film props or new canon."}});
